import{_ as n,o as e,c as i,a2 as t}from"./chunks/framework.C-KFX0n7.js";const m=JSON.parse('{"title":"Pengantar Teken Heula API","description":"","frontmatter":{},"headers":[],"relativePath":"api/pengantar.md","filePath":"api/pengantar.md"}'),r={name:"api/pengantar.md"};function s(l,a,u,g,d,k){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="pengantar-teken-heula-api" tabindex="-1">Pengantar Teken Heula API <a class="header-anchor" href="#pengantar-teken-heula-api" aria-label="Permalink to &quot;Pengantar Teken Heula API&quot;">​</a></h1><p>Selamat datang di Dokumentasi Resmi <strong>Teken Heula API</strong>!</p><p>Teken Heula merupakan sistem sentralisasi layanan <strong>Tanda Tangan Elektronik (E-Sign)</strong> dan <strong>Segel Elektronik (E-Seal)</strong> yang dikembangkan khusus untuk lingkungan Universitas Pendidikan Indonesia (UPI).</p><h2 id="mengapa-teken-heula" tabindex="-1">Mengapa Teken Heula? <a class="header-anchor" href="#mengapa-teken-heula" aria-label="Permalink to &quot;Mengapa Teken Heula?&quot;">​</a></h2><p>Seiring dengan meningkatnya kebutuhan digitalisasi dokumen di lingkungan akademik dan administrasi, UPI membutuhkan sistem penandatanganan elektronik yang tidak hanya sah secara hukum (tersertifikasi oleh Badan Siber dan Sandi Negara / BSrE), tetapi juga mampu menangani beban pemrosesan secara <strong>massal (bulk processing)</strong> dengan performa tinggi.</p><p>API ini dibangun untuk memberikan &quot;jalan tol&quot; bagi seluruh sistem dan aplikasi (<em>Frontend</em> maupun <em>Backend</em>) yang ada di lingkungan UPI agar dapat dengan mudah menyematkan fitur E-Sign dan E-Seal ke dalam dokumen PDF yang mereka hasilkan.</p><h2 id="fitur-unggulan" tabindex="-1">Fitur Unggulan <a class="header-anchor" href="#fitur-unggulan" aria-label="Permalink to &quot;Fitur Unggulan&quot;">​</a></h2><ol><li><strong>Pemrosesan Massal (Bulk)</strong>: Proses tanda tangan dan penyegelan ribuan dokumen elektronik sekaligus dalam satu batch tanpa kendala performa.</li><li><strong>Tersertifikasi BSrE</strong>: Keamanan, integritas, dan validitas hukum dokumen terjamin melalui tanda tangan digital tersertifikasi oleh Badan Siber dan Sandi Negara (BSrE).</li><li><strong>Integrasi Terpusat UPI</strong>: API dirancang andal untuk mendukung kebutuhan layanan penandatanganan dokumen elektronik pada seluruh sistem dan aplikasi di lingkungan Universitas Pendidikan Indonesia (UPI).</li></ol><hr><p>Mari mulai mengintegrasikan sistem Anda dengan API kami. Silakan menuju ke halaman <a href="/docs/api/language-cert.html">Referensi API Core</a>.</p>',10)])])}const p=n(r,[["render",s]]);export{m as __pageData,p as default};
